import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格與已確認例子 route(0,True)=weekday、route(5,True)=weekend

    def test_confirmed_examples(self):
        # 抓「固定回傳同一值」的錯誤
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_weekend_boundary(self):
        # 規格：0..4 weekday、5..6 weekend；抓 4/5 分界錯位（如 >=4 或 >=6）
        for d in (0, 1, 2, 3, 4):
            self.assertEqual(route(d, True), "weekday", d)
        for d in (5, 6):
            self.assertEqual(route(d, True), "weekend", d)

    def test_disabled_returns_paused_for_all_valid_days(self):
        # 規格：合法 day 且 enabled=False -> paused；抓忽略 enabled 的錯誤
        for d in range(7):
            self.assertEqual(route(d, False), "paused", d)

    def test_out_of_range_rejected_even_when_disabled(self):
        # 規格：先驗 day；抓範圍邊界錯（-1、7）及先判 enabled 再驗 day 的順序錯
        for d in (-1, 7):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

    def test_non_integer_rejected(self):
        # 規格：day 必須為整數；字串拒絕案例
        for d in ("0", "5"):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

